-- Synthetic schema matching the public tables created outside this repository.
CREATE TABLE public.op_extra_cargo(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),nome text NOT NULL UNIQUE,setor_padrao text NOT NULL,valor_referencia numeric,ativo boolean NOT NULL DEFAULT true);
CREATE TABLE public.op_extra_cargo_setor(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),cargo_id uuid NOT NULL REFERENCES public.op_extra_cargo,setor text NOT NULL,UNIQUE(cargo_id,setor));
CREATE TABLE public.op_extra_solicitacao(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),unit_id uuid NOT NULL REFERENCES public.units,data_solicitacao date NOT NULL DEFAULT CURRENT_DATE,data_trabalho date NOT NULL,periodo op_extra_periodo,setor text NOT NULL,funcao text NOT NULL,quantidade integer NOT NULL DEFAULT 1 CHECK(quantidade>0),valor_unitario numeric NOT NULL CHECK(valor_unitario>=0),motivo op_extra_motivo NOT NULL,motivo_detalhe text,solicitante_nome text NOT NULL,pagadora op_extra_pagadora,status op_extra_status NOT NULL DEFAULT 'solicitado',emergencial boolean NOT NULL DEFAULT false,observacao text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),valor_total numeric GENERATED ALWAYS AS (quantidade*valor_unitario) STORED);
ALTER TABLE public.op_extra ADD COLUMN solicitacao_id uuid REFERENCES public.op_extra_solicitacao ON DELETE SET NULL;
